struct SlipSession {
    let clip: UInt32
    /// Time under the pointer at mouse-down, so the film keeps pace with
    /// the cursor.
    let grabTime: Ticks

    var delta: Ticks = 0
    var didMove = false

    var op: ReelOp { .slip(clip: clip, delta: delta) }

    mutating func update(time: Ticks) {
        delta = time - grabTime
        didMove = true
    }
